 try{
  const row=(await projectList(true)).find(p=>p.id===b.projectId);
  if(row?.state&&row.state!=='active')throw Error('Az eredeti projekt archivált vagy a lomtárban van. Előbb állítsd vissza a Projektek menüben.');
  if(row?.locked){setBillingOpen(true);throw Error('A projekt zárolt. Helyreállításhoz újítsd meg az előfizetést.')}
  if(!row&&b.revision>0)throw Error('Az eredeti projekt nem érhető el. A helyi másolat megmaradt.');
  const server=row?await readProject(b.projectId):null;
  const copy=recoveryDestination(b,server?.revision??null)==='copy';
  resetEditor(validatePlan(b.plan),copy?uid():b.projectId,copy?0:server?.revision??0,false);
  toast.success(copy?'Újabb szervermentés található: a helyi munka külön új projektként nyílt meg. Mentsd a Mentés gombbal.':'A helyi munkapéldány helyreállítva.');return true;
 }finally{busyRef.current=false;setLoading(false)}
