async function newProject(name:string,copy:boolean){try{if(account){const r=await fetch('/api/billing',{cache:'no-store'}),d=await r.json() as {error?:string;available:number;subscription:{active:boolean}};if(!r.ok)throw Error(d.error);if(d.available<1&&!d.subscription.active){setBillingOpen(true);return}}else if(localProjectList().length>=1){setBillingOpen(true);return}if(copy){void save(name);return}requestSwitch(()=>resetEditor(blankProject(name),uid(),0,false))}catch(e){toast.error(e instanceof Error?e.message:'A projekthelyek nem ellenőrizhetők.')}}
