{(shownFloor.dimensions||[]).map(d=><DimensionMark key={d.id} dimension={d} selected={isSelected('dimensions',d.id)} handles={group.length<2} onPick={tool==='select'?(e,handle)=>pick(e,'dimensions',d.id,handle):undefined}/>)}
{tool==='dimension'&&draft.length>0&&cursor&&<g data-editor-guide="dimension-preview" pointerEvents="none" opacity=".7"><DimensionMark dimension={{id:'preview',name:'Előnézet',a:draft[0],b:cursor,mode:dimensionMode,offset:40}}/></g>}
